(()=>{document.addEventListener("DOMContentLoaded",()=>{let o=document.querySelectorAll("[data-ws-social-sharing]");o.length&&o.forEach(i=>{let s=i.querySelector("[data-ws-copy-link]"),t=i.querySelector("[data-ws-share-message]");!s||!t||s.addEventListener("click",async()=>{let n=s.dataset.shareUrl;if(n){try{await navigator.clipboard.writeText(n),t.textContent="Link copied.",t.classList.add("is-visible")}catch{let e=document.createElement("input");e.value=n,e.setAttribute("readonly",""),e.style.position="absolute",e.style.left="-9999px",document.body.appendChild(e),e.select(),document.execCommand("copy"),e.remove(),t.textContent="Link copied.",t.classList.add("is-visible")}window.setTimeout(()=>{t.classList.remove("is-visible")},2e3)}})})});})();
